command:
/**
 * SVA example: Energy Field Toggle
 * A two-layer energy field around each selected token: the back half is drawn under the token
 * and the front half over it, so the token looks enclosed. Run again to fade it out.
 *
 * Usage: select tokens, run.
 * Requires: Sargas Visual Automation + JB2A (Patreon). No Sequencer needed.
 */
const SVA = game.modules.get("sargas-visual-automation")?.api;
if (!SVA?.ready) return ui.notifications.error("Sargas Visual Automation is not ready.");

const COLOR = "blue"; // blue, green, purple, yellow
const LAYERS = {
  below: `jb2a.energy_field.02.below.${COLOR}`,
  above: `jb2a.energy_field.02.above.${COLOR}`
};
const SCALE = 1.6;
const FADE_MS = 1000;

const tokens = canvas.tokens.controlled;
if (!tokens.length) return ui.notifications.warn("Select at least one token.");
const sceneId = canvas.scene.id;

for (const tok of tokens) {
  // Both halves share one name, so a single end() removes the pair.
  const name = `sva-energy-field:${tok.id}`;
  if (SVA.effects.list({ sceneId, name }).length) {
    await SVA.effects.end({ name, sceneId });
    continue;
  }
  const seq = SVA.sequence();
  for (const [half, file] of Object.entries(LAYERS)) {
    seq
      .effect()
      .file(file)
      .attachTo(tok.id)
      .scaleToObject(SCALE)
      .layer(half === "below" ? "belowTokens" : "aboveTokens")
      .fadeIn(FADE_MS, { ease: "easeOutCubic" })
      .fadeOut(FADE_MS, { ease: "easeOutCubic" })
      .persist(true)
      .name(name);
  }
  await seq.play();
}
